                    "name": "guest_shop_orders_amount_check",
                    "type": "c",
                    "validated": true,
                    "deferrable": false,
                    "definition": "CHECK (unit_amount > 0::numeric AND total_amount > 0::numeric AND payment_fee_amount >= 0::numeric AND discount_amount >= 0::numeric AND (list_unit_amount IS NULL OR list_unit_amount > 0::numeric) AND (discount_amount = 0::numeric OR list_unit_amount IS NOT NULL) AND (list_unit_amount IS NULL OR discount_amount < round(list_unit_amount * quantity::numeric, 2) AND discount_amount <= round(list_unit_amount * quantity::numeric * 0.5, 2)) AND payment_fee_amount <= (round(unit_amount * quantity::numeric * 0.1, 2) + 0.01) AND total_amount = (unit_amount * quantity::numeric + payment_fee_amount))"
