                    "name": "guest_shop_orders_discount_code_check",
                    "type": "c",
                    "validated": true,
                    "deferrable": false,
                    "definition": "CHECK (discount_code IS NULL OR discount_code::text ~ '^[A-Z0-9][A-Z0-9_-]{0,49}$'::text)"
                },
                {
                    "name": "guest_shop_orders_expiry_check",
                    "type": "c",
                    "validated": true,
